/* @autogenerated */
import { matchColumns } from './column-match';
import { readWorkbook } from './excel-reader';
import { buildTemplate, ImportTemplate } from './excel-writer';

const template: ImportTemplate = {
  dataSheet: 'Datos',
  headers: ['Nombre', 'correo electrónico', 'situación en el proceso de aprobación'],
  helpSheet: 'Instrucciones: columnas [ayuda] muy larga para Excel',
  help: [
    ['Columna', 'Obligatoria', 'Formato'],
    ['Nombre', 'clave', 'texto'],
    ['correo electrónico', '', 'texto'],
    ['situación en el proceso de aprobación', '', 'ACEPTADO / PREVIO'],
  ],
};

async function asFile(): Promise<File> {
  const XLSX = await import('xlsx');
  const bytes = XLSX.write(await buildTemplate(template), { type: 'array', bookType: 'xlsx' });
  return new File([bytes], 'plantilla.xlsx');
}

describe('excel-writer', () => {
  it('writes an empty data sheet with the headers first and the instructions after it', async () => {
    const [data, help] = await readWorkbook(await asFile());

    expect(data.name).toBe('Datos');
    expect(data.headers).toEqual(template.headers);
    expect(data.rows).toEqual([]);
    expect(help.name).toBe('Instrucciones  columnas  ayuda ');
    expect(help.headers).toEqual(['Columna', 'Obligatoria', 'Formato']);
    expect(help.rows.map((row) => row.cells[0])).toEqual(template.headers);
  });

  it('produces headers that the import matches on its own', async () => {
    const [data] = await readWorkbook(await asFile());

    const mapping = matchColumns(data.headers, [
      { field: 'name', names: ['Nombre', 'name'] },
      { field: 'email', names: ['correo electrónico', 'email'] },
      { field: 'approvalStatus', names: ['situación en el proceso de aprobación', 'approvalStatus'] },
    ]);

    expect(mapping).toEqual({ name: 0, email: 1, approvalStatus: 2 });
  });
});
